      padding: 1rem 1.75rem;
      border-radius: 4px;
      font-size: 1.05rem;
      font-weight: 700;
      cursor: pointer;
      white-space: nowrap;
      transition: background 150ms, transform 100ms;
      letter-spacing: 0.01em;
