    .carousel-track-outer {
      overflow: hidden;
      border-radius: 6px;
    }

    .carousel-track {
      display: flex;
      gap: 0.75rem;
      transition: transform 400ms cubic-bezier(0.25, 0.46, 0.45, 0.94);
      will-change: transform;
    }

    .carousel-card {
      flex: 0 0 160px;
      position: relative;
      border-radius: 6px;
      overflow: hidden;
      cursor: pointer;
      transition: transform 200ms ease;
    }
    .carousel-card:hover { transform: scale(1.04); }

    .carousel-card-img {
      width: 160px;
      height: 220px;
      object-fit: cover;
      display: block;
      background-color: var(--bg-card2);
      background-size: cover;
      background-position: center;
    }

    .rank-number {
      position: absolute;
      bottom: -8px;
      left: -6px;
      font-size: 6rem;
      font-weight: 900;
      line-height: 1;
      color: transparent;
      -webkit-text-stroke: 3px rgba(255,255,255,0.85);
      pointer-events: none;
      letter-spacing: -0.06em;
      text-shadow: none;
      user-select: none;
    }

    .card-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(0,0,0,0.7) 0%, transparent 50%);
    }

    .card-title-label {
      position: absolute;
      bottom: 0.5rem;
      left: 0.5rem;
      right: 0.5rem;
      font-size: 0.7rem;
      font-weight: 600;
      color: rgba(255,255,255,0.9);
      text-overflow: ellipsis;
      overflow: hidden;
      white-space: nowrap;
      padding-left: 3.5rem;
    }

    .carousel-nav {
      display: flex;
      justify-content: flex-end;
      gap: 0.5rem;
      margin-bottom: 1rem;
    }

    .carousel-btn {
      background: rgba(255,255,255,0.1);
      border: 1px solid var(--border);
      color: var(--white);
      width: 40px;
      height: 40px;
      border-radius: 50%;
      font-size: 1.1rem;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background 150ms;
    }
    .carousel-btn:hover { background: rgba(255,255,255,0.2); }
    .carousel-btn:disabled { opacity: 0.3; cursor: default; }

    /* ── FEATURES ────────────────────────────────────────── */
    .features-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
      gap: 1rem;
    }

    .feature-card {
      background: var(--bg-card);
      border-radius: 8px;
      padding: 1.75rem 1.5rem;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      min-height: 200px;
      position: relative;
      overflow: hidden;
      border: 1px solid var(--border);
      transition: border-color 200ms;
    }
    .feature-card:hover { border-color: rgba(229,9,20,0.4); }

    .feature-card h3 {
      font-size: 1.3rem;
      font-weight: 800;
      line-height: 1.2;
      letter-spacing: -0.02em;
      margin-bottom: 0.75rem;
    }

    .feature-card p {
      color: var(--gray);
      font-size: 0.9rem;
      line-height: 1.55;
      flex: 1;
    }

    .feature-icon {
      margin-top: 1.5rem;
      align-self: flex-end;
      opacity: 0.8;
    }

    .feature-icon svg {
      width: 48px;
      height: 48px;
      stroke: var(--white);
      fill: none;
      stroke-width: 1.5;
    }

    /* ── FAQ ─────────────────────────────────────────────── */
    .faq-list {
      display: flex;
      flex-direction: column;
      gap: 0.5rem;
      max-width: 860px;
      margin: 0 auto;
    }

    .faq-item {
      background: var(--bg-card);
      border-radius: 4px;
      overflow: hidden;
    }

    .faq-question {
      width: 100%;
      background: none;
      border: none;
      color: var(--white);
      font-family: var(--font);
      font-size: 1.1rem;
      font-weight: 600;
      text-align: left;
      padding: 1.2rem 1.5rem;
      cursor: pointer;
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      transition: background 150ms;
    }
    .faq-question:hover { background: rgba(255,255,255,0.05); }

    .faq-icon {
      flex-shrink: 0;
      width: 28px;
      height: 28px;
      background: var(--gray);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: transform 300ms ease, background 200ms;
    }
    .faq-item.open .faq-icon {
      transform: rotate(45deg);
      background: var(--red);
    }

    .faq-icon svg {
      width: 16px; height: 16px;
      stroke: var(--bg);
      stroke-width: 2.5;
    }

    .faq-answer {
      max-height: 0;
      overflow: hidden;
      transition: max-height 400ms cubic-bezier(0.25, 0.46, 0.45, 0.94);
    }
    .faq-item.open .faq-answer { max-height: 400px; }

    .faq-answer-inner {
      padding: 0.25rem 1.5rem 1.5rem;
      color: var(--gray);
      font-size: 0.95rem;
      line-height: 1.65;
      border-top: 1px solid rgba(255,255,255,0.07);
    }

    /* ── CTA SECTION ─────────────────────────────────────── */
    .cta-section {
      text-align: center;
      padding: 4rem 1.5rem;
      border-top: 1px solid var(--border);
    }

    .cta-section h2 {
      font-size: clamp(1.75rem, 4vw, 2.5rem);
      font-weight: 900;
      letter-spacing: -0.03em;
      margin-bottom: 0.5rem;
    }

    .cta-section .hero-sub {
      margin-bottom: 1.5rem;
    }

    /* ── FOOTER ──────────────────────────────────────────── */
    footer {
      padding: 3rem 3.5rem 2rem;
      border-top: 1px solid var(--border);
    }

    .footer-contact {
      color: var(--gray);
      margin-bottom: 1.5rem;
      font-size: 0.95rem;
    }

    .footer-contact a {
      color: var(--gray);
      text-decoration: underline;
    }

    .footer-links {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
      gap: 0.5rem 1rem;
      margin-bottom: 2rem;
    }

    .footer-links a {
      color: var(--gray);
      font-size: 0.8rem;
      text-decoration: none;
      transition: color 150ms;
    }
    .footer-links a:hover { color: var(--white); }

    .footer-bottom {
      display: flex;
      align-items: center;
      gap: 1rem;
      flex-wrap: wrap;
    }

    .footer-legal {
      color: rgba(163,163,163,0.6);
      font-size: 0.75rem;
      margin-top: 1rem;
    }

    /* ── MOBILE ──────────────────────────────────────────── */
    @media (max-width: 768px) {
      header { padding: 1rem 1.25rem; }
      .logo { font-size: 1.4rem; }

      .hero { min-height: 75vh; padding: 7rem 1.25rem 4rem; }
      .hero h1 { font-size: 2rem; }
      .hero-sub { font-size: 1rem; }
      .email-form { flex-direction: column; }
      .email-form input[type="email"],
      .btn-primary { width: 100%; }

      .section { padding: 2.5rem 1.25rem; }
      footer { padding: 2.5rem 1.25rem 1.5rem; }

      .carousel-card { flex: 0 0 130px; }
      .carousel-card-img { width: 130px; height: 185px; }
      .rank-number { font-size: 4.5rem; }
    }

    @media (max-width: 480px) {
      .features-grid { grid-template-columns: 1fr; }
    }

    /* ── TOUCH SCROLL ────────────────────────────────────── */
    @media (hover: none) {
      .carousel-track-outer {
        overflow-x: auto;
        -webkit-overflow-scrolling: touch;
        scrollbar-width: none;
      }
      .carousel-track-outer::-webkit-scrollbar { display: none; }
      .carousel-track { transition: none; }
    }

    /* ── ANIMATIONS ──────────────────────────────────────── */
    @keyframes fadeUp {
      from { opacity: 0; transform: translateY(24px); }
      to   { opacity: 1; transform: translateY(0); }
    }
    .hero-content { animation: fadeUp 600ms ease-out both; }
    .hero h1 { animation-delay: 100ms; }
    .hero-sub { animation-delay: 200ms; }
  </style>
